// Copies the legal documents (legal/*.md and legal/details.json in the repository root, the same
// files the iPhone app and the website use) into src/screens/legal-docs.gen.ts, because the
// desktop build has no loader for Markdown files. The page at /legal/:doc draws them.
//
//   cd desktop && node scripts/legal.mjs
//
// Run it after changing a document or details.json, and commit the generated file with them.
import fs from 'node:fs';
import path from 'node:path';

const here = path.dirname(new URL(import.meta.url).pathname);
const legal = path.resolve(here, '../../legal');
const out = path.resolve(here, '../src/screens/legal-docs.gen.ts');

// The address on the desktop (/legal/<id>) for each file; the documents link to each other by
// their website paths ("/community-guidelines"), which the page turns into these.
const DOCS = [
  { id: 'privacy', file: 'privacy.md' },
  { id: 'terms', file: 'terms.md' },
  { id: 'guidelines', file: 'community-guidelines.md' },
  { id: 'child-safety', file: 'child-safety.md' },
  { id: 'copyright', file: 'copyright.md' },
];

const details = JSON.parse(fs.readFileSync(path.join(legal, 'details.json'), 'utf8'));
const markdown = {};
for (const d of DOCS) markdown[d.id] = fs.readFileSync(path.join(legal, d.file), 'utf8').replace(/\r\n?/g, '\n');

const body = [
  '// Generated by scripts/legal.mjs from legal/*.md and legal/details.json. Do not edit by hand:',
  '// change the files in legal/ and run `node scripts/legal.mjs` in desktop/.',
  '',
  `export const LEGAL_DETAILS: Record<string, string> = ${JSON.stringify(details, null, 2)};`,
  '',
  `/** Each document's Markdown, by its address on the desktop (/legal/<id>). */`,
  `export const LEGAL_MARKDOWN: Record<string, string> = ${JSON.stringify(markdown, null, 2)};`,
  '',
  `/** The website path each document is linked by inside the others. */`,
  `export const LEGAL_PATHS: Record<string, string> = ${JSON.stringify(Object.fromEntries(DOCS.map((d) => ['/' + d.file.replace(/\.md$/, ''), d.id])), null, 2)};`,
  '',
].join('\n');
fs.writeFileSync(out, body);
console.log('wrote', path.relative(process.cwd(), out), Object.keys(markdown).join(', '));
